fn sgn(v: i32) -> i32 {
    if v > 0 { return 1; }
    if v < 0 { return -1; }
    0
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 4 {
            host::display::state_set(8 + i * 4, (80 + i * 90) * 8);
            host::display::state_set(9 + i * 4, (70 + i * 80) * 8);
            host::display::state_set(10 + i * 4, 10 - i * 5);
            host::display::state_set(11 + i * 4, 4 + i * 3);
            i = i + 1;
        }
    }
    let mut sx: i32 = 0;
    let mut sy: i32 = 0;
    let mut i: i32 = 0;
    while i < 4 {
        sx = sx + host::display::state_get(8 + i * 4);
        sy = sy + host::display::state_get(9 + i * 4);
        i = i + 1;
    }
    let cx: i32 = sx / 4;
    let cy: i32 = sy / 4;
    host::display::clear(0x08101c);
    let pal: [i32; 4] = [0xff6050, 0x60ff70, 0x60a0ff, 0xffd050];
    i = 0;
    while i < 4 {
        let b: i32 = 8 + i * 4;
        let mut x: i32 = host::display::state_get(b);
        let mut y: i32 = host::display::state_get(b + 1);
        let mut vx: i32 = host::display::state_get(b + 2);
        let mut vy: i32 = host::display::state_get(b + 3);
        vx = vx + (cx - x) / 64;
        vy = vy + (cy - y) / 64;
        let mut j: i32 = 0;
        while j < 4 {
            if j != i {
                let ox: i32 = host::display::state_get(8 + j * 4);
                let oy: i32 = host::display::state_get(9 + j * 4);
                let dx: i32 = x - ox;
                let dy: i32 = y - oy;
                if dx > -240 && dx < 240 && dy > -240 && dy < 240 {
                    vx = vx + sgn(dx) * 3;
                    vy = vy + sgn(dy) * 3;
                }
            }
            j = j + 1;
        }
        if vx > 22 { vx = 22; }
        if vx < -22 { vx = -22; }
        if vy > 22 { vy = 22; }
        if vy < -22 { vy = -22; }
        x = x + vx;
        y = y + vy;
        if x < 0 { x = x + w * 8; }
        if x >= w * 8 { x = x - w * 8; }
        if y < 0 { y = y + h * 8; }
        if y >= h * 8 { y = y - h * 8; }
        host::display::state_set(b, x);
        host::display::state_set(b + 1, y);
        host::display::state_set(b + 2, vx);
        host::display::state_set(b + 3, vy);
        host::display::fill_rect(x / 8 - 4, y / 8 - 4, 8, 8, pal[i]);
        i = i + 1;
    }
    host::display::fill_rect(cx / 8 - 1, cy / 8 - 1, 3, 3, 0x405060);
    host::display::present();
}
